namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Interfaces.ACL;

/// <summary>
///     A reading attributed to an animal. Null metrics were invalid or not captured; they are never zero substitutes.
/// </summary>
/// <param name="ReadingId">The reading identifier generated by the device firmware.</param>
/// <param name="DeviceId">The device that captured the reading.</param>
/// <param name="CattleId">The animal the reading is attributed to.</param>
/// <param name="RecordedAt">The instant the device captured the reading.</param>
/// <param name="BodyTemperatureCelsius">The body temperature in degrees Celsius.</param>
/// <param name="ActivityIndex">The activity index.</param>
/// <param name="RuminationMinutes">The rumination minutes.</param>
/// <param name="Latitude">The latitude in decimal degrees.</param>
/// <param name="Longitude">The longitude in decimal degrees.</param>
/// <param name="AccuracyMeters">The declared position accuracy in meters.</param>
public record MonitoringReadingRecord(
    Guid ReadingId,
    Guid DeviceId,
    Guid CattleId,
    DateTimeOffset RecordedAt,
    double? BodyTemperatureCelsius,
    double? ActivityIndex,
    double? RuminationMinutes,
    double? Latitude,
    double? Longitude,
    double? AccuracyMeters);
